function AssetLogo({market}){if(market.ticker.startsWith('BTC'))return <span className="asset-logo btc-logo" aria-label="Bitcoin logo"><img src="https://assets.coingecko.com/coins/images/1/large/bitcoin.png" alt=""/></span>;if(market.ticker.startsWith('DOGE'))return <span className="asset-logo doge-logo" aria-label="Dogecoin logo"><img src="https://assets.coingecko.com/coins/images/5/large/dogecoin.png" alt=""/></span>;if(market.ticker.startsWith('ETH'))return <span className="asset-logo eth-logo" aria-label="Ethereum logo"><svg viewBox="0 0 40 40" role="img"><title>Ethereum</title><polygon points="20,2 8,21 20,16" fill="#8C8C8C"/><polygon points="20,2 32,21 20,16" fill="#343434"/><polygon points="8,21 20,16 20,28" fill="#393939"/><polygon points="32,21 20,16 20,28" fill="#8C8C8C"/><polygon points="8,23 20,38 20,30" fill="#8C8C8C"/><polygon points="32,23 20,38 20,30" fill="#343434"/></svg></span>;if(market.ticker.startsWith('SOL'))return <span className="asset-logo sol-logo" aria-label="Solana logo"><img src="https://solana.com/src/img/branding/solanaLogoMark.svg" alt=""/></span>;if(market.ticker.startsWith('GRAM'))return <span className="asset-logo gram-logo" aria-label="Gram token logo"><svg viewBox="0 0 80 80" role="img"><title>Official Gram logo</title><path fill="#30A1F5" d="M52.017 12.097H27.984c-3.201 0-4.802 0-6.25.448a10 10 0 0 0-3.496 1.909c-1.159.975-2.024 2.322-3.755 5.014l-7.64 11.884c-1.144 1.78-1.716 2.668-1.87 3.605a4.6 4.6 0 0 0 .263 2.45c.35.882 1.098 1.63 2.593 3.125L36.217 68.92c1.325 1.324 1.987 1.986 2.75 2.234a3.34 3.34 0 0 0 2.067 0c.763-.248 1.425-.91 2.75-2.234l28.388-28.388c1.495-1.495 2.243-2.243 2.593-3.125.31-.778.4-1.625.263-2.45-.155-.937-.727-1.826-1.87-3.605l-7.64-11.884c-1.73-2.692-2.596-4.039-3.756-5.014a10 10 0 0 0-3.496-1.91c-1.448-.447-3.048-.447-6.249-.447"/><path fill="#fff" d="M47.465 21.472c.39-1.055 1.883-1.055 2.274 0l2.698 7.292a1.6 1.6 0 0 0 .945.946l7.293 2.698c1.055.39 1.055 1.883 0 2.274l-7.293 2.698a1.6 1.6 0 0 0-.945.945l-2.698 7.293c-.39 1.055-1.883 1.055-2.274 0l-2.698-7.293a1.6 1.6 0 0 0-.946-.945l-7.292-2.698c-1.055-.39-1.055-1.883 0-2.274l7.292-2.698a1.6 1.6 0 0 0 .946-.946z"/></svg></span>;return <span className="coin-symbol" style={{color:market.color}}>{market.symbol}</span>}
function MarketChart({market}){const closes=[34,39,36,44,41,47,43,51,48,45,54,50,58,55,61,57,65,60,56,63,69,64,72,68,74,70,78,73,81,77,84,80,88,83];const candles=closes.map((close,i)=>{const open=i===0?close-3:closes[i-1]+((i%3)-1)*2;const high=Math.max(open,close)+2+(i%3);const low=Math.min(open,close)-2-(i%2);return {x:42+i*15.2,open,close,high,low,up:close>=open}});const y=v=>174-v*1.45;const average=candles.map((c,i)=>({x:c.x+4,y:y(closes.slice(Math.max(0,i-4),i+1).reduce((a,b)=>a+b,0)/closes.slice(Math.max(0,i-4),i+1).length)}));const line=average.map((p,i)=>(i?'L':'M')+' '+p.x+' '+p.y).join(' ');return <div className="chart-panel pro-chart"><div className="chart-meta"><div><span>Illustrative price</span><strong>{market.price.toLocaleString('en-US',{minimumFractionDigits:2,maximumFractionDigits:4})}</strong></div><span className={'change '+(market.change>=0?'positive':'negative')}>{market.change>0?'+':''}{market.change}% <small>24h</small></span></div><div className="chart-legend"><span><i className="legend-candle"/> Price action</span><span><i className="legend-average"/> Trend line</span><span className="chart-period">ILLUSTRATIVE · 1D</span></div><svg className="chart-visual pro-candles" viewBox="0 0 620 220" preserveAspectRatio="none" role="img" aria-label={market.name+' candlestick market chart preview'}>{[35,70,105,140,175].map(v=><line key={v} x1="24" x2="590" y1={v} y2={v} className="chart-grid-line"/>)}{[110,230,350,470,590].map(v=><line key={v} x1={v} x2={v} y1="18" y2="190" className="chart-grid-line vertical"/>)}<path d={line} className="chart-trend-line"/>{candles.map((c,i)=><g key={i} className={c.up?'candle-up':'candle-down'}><line x1={c.x+4} x2={c.x+4} y1={y(c.high)} y2={y(c.low)} className="candle-wick"/><rect x={c.x} y={Math.min(y(c.open),y(c.close))} width="8" height={Math.max(3,Math.abs(y(c.open)-y(c.close)))} rx="1.5" className="candle-body"/></g>)}{candles.map((c,i)=><rect key={'v'+i} x={c.x} y={194+(i%4)*2} width="8" height={18-(i%4)*2} rx="1" className={c.up?'volume-up':'volume-down'}/>)}</svg><div className="chart-axis"><span>00:00</span><span>06:00</span><span>12:00</span><span>18:00</span><span>Now</span></div><div className="chart-timeframes">{['15m','1H','4H','1D','1W'].map(t=><span key={t} className={t==='1D'?'active':''}>{t}</span>)}</div></div>}
function Onboarding({onComplete}){const [step,setStep]=useState(0);const slides=[{icon:Sparkles,kicker:'WELCOME TO PEXORIY',title:'Practice. Compete. Grow.',body:'A community-powered crypto practice platform with AI tools, skill-building missions, and shared challenges.',color:'lime',tag:'YOUR SPACE TO LEVEL UP'},{icon:Layers3,kicker:'THREE DISTINCT ASSETS',title:'Know what each balance means.',body:'Trade Credits (TC) power simulated practice trades. AI Credits (AC) power AI operations. Neither is cash.',color:'violet',tag:'TC = PRACTICE · AC = AI'},{icon:CircleDollarSign,kicker:'THE PEXORIY TOKEN',title:'PXY is the project token.',body:'PXY is the actual Pexoriy project token, separate from TC and AC. It is pre-launch; community challenges are the primary distribution path, with any other allocation governed by published campaign rules.',color:'blue',tag:'PXY = PROJECT TOKEN'},{icon:Trophy,kicker:'YOUR COMMUNITY LOOP',title:'Show up. Build skill. Bring your people.',body:'Keep a gentle daily streak, complete missions, join the Arena, and invite friends into community milestones.',color:'orange',tag:'YOUR JOURNEY STARTS HERE'}];const slide=slides[step],Icon=slide.icon;return <div className="onboarding-backdrop"><section className="onboarding-modal" role="dialog" aria-modal="true" aria-label="Welcome to Pexoriy"><div className="onboarding-top"><Brand/><button className="onboarding-skip" onClick={onComplete}>Skip</button></div><div className={'onboarding-art onboarding-art-'+slide.color}><div className="onboarding-orbit orbit-one"/><div className="onboarding-orbit orbit-two"/><div className="onboarding-icon"><Icon size={34}/></div><span className="onboarding-spark spark-one">✦</span><span className="onboarding-spark spark-two">✧</span></div><span className="onboarding-kicker">{slide.kicker}</span><h2>{slide.title}</h2><p>{slide.body}</p><span className="onboarding-tag">{slide.tag}</span><div className="onboarding-footer"><div className="onboarding-dots">{slides.map((x,i)=><span key={x.kicker} className={i===step?'active':''}/>)}</div><Btn kind="lime" onClick={()=>step===slides.length-1?onComplete():setStep(v=>v+1)}>{step===slides.length-1?'Enter Pexoriy':'Continue'} <ArrowRight size={15}/></Btn></div></section></div>}
