function MarketTable({choose,navigate}){return <div className="market-table"><div className="market-table-head"><span>ASSET</span><span>LAST PRICE</span><span>24H CHANGE</span><span/></div>{markets.map(m=><div className="market-row" key={m.ticker}><div className="market-asset"><AssetLogo market={m}/><div><strong>{m.name}</strong><span>{m.ticker}</span></div></div><strong className="market-price">{'$'+money(m.price)}</strong><span className={'change '+(m.change>=0?'positive':'negative')}>{m.change>=0?<ArrowUpRight size={14}/>:<ArrowDownRight size={14}/>} {m.change>0?'+':''}{m.change}%</span><button className="row-action" onClick={()=>{choose(m);navigate('Practice Trading')}}><ArrowUpRight size={17}/></button></div>)}</div>}
